insert into public.media_aids (slug,kind,title,description,levels,subject,topic,orient,pages,cover_url,pdf_url,bw_url,page_urls,review_note,status,sort_order) values
('bd-birthdays','board','لوحة أعياد ميلاد الصف','لوحة للحائط بالأشهر الميلادية الاثني عشر يكتب كل طالب اسمه تحت شهر ميلاده، لتبادل التهنئة وتعلّم أسماء الأشهر.',array['g1','g2','g3','g4']::text[],'المهارات الحياتية','المناسبات','landscape',1,'images/media/bd-birthdays/thumb.webp','files/media/bd-birthdays.pdf','files/media/bd-birthdays-bw.pdf',array['images/media/bd-birthdays/p01.webp']::text[],'محتوى أصلي من إعداد زاد (توليد برمجي)؛ لم يراجعه معلم أو جهة تعليمية بعد. لوحة تعليمية أصلية من إعداد زاد، تُطبع بحجم ١٠٠٪ على ورق A4 وتُعلّق أو تُستعمل في الصف أو البيت. لم تُراجَع من جهة تعليمية رسمية.','published',10),
('bd-star-chart','board','لوحة النجوم الأسبوعية','لوحة تحفيز: جدول بأيام الأسبوع من الأحد إلى الخميس وسبعة أسطر لأسماء الطلاب، يلوّن المعلم نجمة لكل يوم يلتزم فيه الطالب بهدف الأسبوع.',array['a5','a6','g1','g2','g3','g4']::text[],'المهارات الحياتية','التحفيز','landscape',1,'images/media/bd-star-chart/thumb.webp','files/media/bd-star-chart.pdf','files/media/bd-star-chart-bw.pdf',array['images/media/bd-star-chart/p01.webp']::text[],'محتوى أصلي من إعداد زاد (توليد برمجي)؛ لم يراجعه معلم أو جهة تعليمية بعد. لوحة تعليمية أصلية من إعداد زاد، تُطبع بحجم ١٠٠٪ على ورق A4 وتُعلّق أو تُستعمل في الصف أو البيت. لم تُراجَع من جهة تعليمية رسمية.','published',11),
('bd-timetable','board','الجدول الأسبوعي للحصص','جدول فارغ بأيام الدراسة من الأحد إلى الخميس وست حصص في اليوم تُكتب فيه المواد بخط اليد، مع خانة للاستراحة.',array['g1','g2','g3','g4']::text[],'المهارات الحياتية','التنظيم','landscape',1,'images/media/bd-timetable/thumb.webp','files/media/bd-timetable.pdf','files/media/bd-timetable-bw.pdf',array['images/media/bd-timetable/p01.webp']::text[],'محتوى أصلي من إعداد زاد (توليد برمجي)؛ لم يراجعه معلم أو جهة تعليمية بعد. لوحة تعليمية أصلية من إعداد زاد، تُطبع بحجم ١٠٠٪ على ورق A4 وتُعلّق أو تُستعمل في الصف أو البيت. لم تُراجَع من جهة تعليمية رسمية.','published',12),
('bd-reading-log','board','سجل قراءتي','سجل قراءة من ثمانية أسطر: اسم الكتاب وعدد صفحاته وتاريخ القراءة وتقييم الطالب بخمس نجوم، لتشجيع القراءة المنتظمة.',array['g1','g2','g3','g4']::text[],'اللغة العربية','القراءة','landscape',1,'images/media/bd-reading-log/thumb.webp','files/media/bd-reading-log.pdf','files/media/bd-reading-log-bw.pdf',array['images/media/bd-reading-log/p01.webp']::text[],'محتوى أصلي من إعداد زاد (توليد برمجي)؛ لم يراجعه معلم أو جهة تعليمية بعد. لوحة تعليمية أصلية من إعداد زاد، تُطبع بحجم ١٠٠٪ على ورق A4 وتُعلّق أو تُستعمل في الصف أو البيت. لم تُراجَع من جهة تعليمية رسمية.','published',13),
('bd-word-wall','board','حائط الكلمات','لوحة بالحروف الهجائية الثمانية والعشرين، في كل مربع حرف كبير ومساحة لكتابة الكلمات الجديدة التي يتعلمها الطالب وتبدأ بهذا الحرف.',array['g1','g2','g3']::text[],'اللغة العربية','المفردات','landscape',1,'images/media/bd-word-wall/thumb.webp','files/media/bd-word-wall.pdf','files/media/bd-word-wall-bw.pdf',array['images/media/bd-word-wall/p01.webp']::text[],'محتوى أصلي من إعداد زاد (توليد برمجي)؛ لم يراجعه معلم أو جهة تعليمية بعد. لوحة تعليمية أصلية من إعداد زاد، تُطبع بحجم ١٠٠٪ على ورق A4 وتُعلّق أو تُستعمل في الصف أو البيت. لم تُراجَع من جهة تعليمية رسمية.','published',14),
('bd-feelings-checkin','board','لوحة مشاعري اليوم','لوحة بست مشاعر بوجوه كرتونية (فرحان وحزين وغاضب وخائف ونعسان ومستغرب) يكتب الطفل اسمه أو يلصق بطاقته تحت الشعور الذي يحسّ به، لتعزيز التعبير عن المشاعر.',array['a4','a5','a6','g1','g2','g3']::text[],'المهارات الحياتية','المشاعر','landscape',1,'images/media/bd-feelings-checkin/thumb.webp','files/media/bd-feelings-checkin.pdf','files/media/bd-feelings-checkin-bw.pdf',array['images/media/bd-feelings-checkin/p01.webp']::text[],'محتوى أصلي من إعداد زاد (توليد برمجي)؛ لم يراجعه معلم أو جهة تعليمية بعد. لوحة تعليمية أصلية من إعداد زاد، تُطبع بحجم ١٠٠٪ على ورق A4 وتُعلّق أو تُستعمل في الصف أو البيت. لم تُراجَع من جهة تعليمية رسمية.','published',15)
